import { describe, expect, it } from 'vitest';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * CR-82 (FF-5 / FF-16): every animation must have a reduced-motion twin.
 * - every class in index.css carrying an `animation:` declaration is
 *   neutralized inside a `@media (prefers-reduced-motion: reduce)` block;
 * - every `animate-*` generated by tailwind.config.js is either paired
 *   with `motion-reduce:` at its call sites or gated by a JS
 *   usePrefersReducedMotion branch in that file;
 * - every keyframe (index.css + tailwind.config.js) animates only
 *   transform/opacity (compositor-only, R-01);
 * - `ease-toy` appears only next to press-release / snap-in (R-v5-05);
 * - explicit asserts for .tile-shake and .dart-arrow (spec D3).
 */
const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const CSS_PATH = path.join(REPO_ROOT, 'src/index.css');
const TW_PATH = path.join(REPO_ROOT, 'tailwind.config.js');
const SRC_DIR = path.join(REPO_ROOT, 'src');

const css = readFileSync(CSS_PATH, 'utf8');
const twConfig = readFileSync(TW_PATH, 'utf8');

/** Class selectors that carry an `animation:` declaration in index.css. */
function animatingCssClasses(source: string): Set<string> {
  const classes = new Set<string>();
  const ruleRe = /([^{}@]+)\{([^{}]*)\}/g;
  let m: RegExpExecArray | null;
  while ((m = ruleRe.exec(source))) {
    const [, selector, body] = m;
    if (!/\banimation\s*:/.test(body) || /\banimation\s*:\s*none/.test(body)) continue;
    for (const cls of selector.matchAll(/\.([a-zA-Z][\w-]*)/g)) classes.add(cls[1]);
  }
  return classes;
}

/** Selectors neutralized inside ALL prefers-reduced-motion blocks. */
function reducedMotionSelectors(source: string): Set<string> {
  const names = new Set<string>();
  const blockRe = /@media\s*\(prefers-reduced-motion:\s*reduce\)[^{]*\{([\s\S]*?)\}\s*\}/g;
  let m: RegExpExecArray | null;
  while ((m = blockRe.exec(source))) {
    const block = m[1];
    for (const cls of block.matchAll(/\.([a-zA-Z][\w-]*)/g)) names.add(cls[1]);
  }
  return names;
}

function collectSource(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const full = path.join(dir, entry);
    if (statSync(full).isDirectory()) {
      collectSource(full, out);
    } else if (/\.(ts|tsx|js)$/.test(entry) && !/\.test\.tsx?$/.test(entry)) {
      out.push(full);
    }
  }
  return out;
}

describe('reduced-motion guard (CR-82 FF-5)', () => {
  it('every index.css animation class is neutralized in a reduced block', () => {
    const animated = animatingCssClasses(css);
    const reduced = reducedMotionSelectors(css);
    const missing = [...animated].filter((c) => !reduced.has(c));
    expect(missing).toEqual([]);
  });

  it('explicit: .tile-shake and .dart-arrow are in a reduced block (D3)', () => {
    const reduced = reducedMotionSelectors(css);
    expect(reduced.has('tile-shake')).toBe(true);
    expect(reduced.has('dart-arrow')).toBe(true);
  });

  it('every tailwind animate-* is reduced at call sites or JS-gated', () => {
    const animNames = new Set<string>();
    const animBlock = twConfig.match(/animation\s*:\s*\{([\s\S]*?)\n\s{8}\}/)?.[1] ?? '';
    for (const m of animBlock.matchAll(/'([a-z-]+)'\s*:/g)) animNames.add(m[1]);
    const files = collectSource(SRC_DIR);
    const offenders: string[] = [];
    for (const name of animNames) {
      const usage = new RegExp(`animate-${name}\\b`, 'g');
      for (const file of files) {
        const source = readFileSync(file, 'utf8');
        if (!usage.test(source)) continue;
        const jsGated = /usePrefersReducedMotion/.test(source);
        const lines = source.split('\n');
        lines.forEach((line, i) => {
          if (usage.test(line) && !/motion-reduce/.test(line) && !jsGated) {
            offenders.push(`${path.relative(REPO_ROOT, file)}:${i + 1} animate-${name}`);
          }
        });
      }
    }
    expect(offenders).toEqual([]);
  });
});

describe('compositor-only motion (CR-82 FF-16)', () => {
  const ALLOWED_PROPS = new Set(['transform', 'opacity', 'from', 'to']);

  function cssKeyframeProperties(source: string): string[] {
    const stripped = source.replace(/\/\*[\s\S]*?\*\//g, '');
    const props: string[] = [];
    const kfRe = /@keyframes\s+[\w-]+\s*\{([\s\S]*?)\n\}/g;
    let m: RegExpExecArray | null;
    while ((m = kfRe.exec(stripped))) {
      for (const dm of m[1].matchAll(/([a-zA-Z][\w-]*)\s*:/g)) {
        props.push(dm[1]);
      }
    }
    return props;
  }

  it('index.css keyframes animate only transform/opacity', () => {
    const bad = cssKeyframeProperties(css).filter((p) => !ALLOWED_PROPS.has(p));
    expect(bad).toEqual([]);
  });

  it('tailwind keyframes animate only transform/opacity', () => {
    const block = twConfig.match(/keyframes\s*:\s*\{([\s\S]*?)\},\s*\n\s*animation\s*:/);
    expect(block).not.toBeNull();
    const keyframeSrc = block![1].replace(/\/\/[^\n]*/g, '').replace(/\/\*[\s\S]*?\*\//g, '');
    const props: string[] = [];
    for (const dm of keyframeSrc.matchAll(/([a-zA-Z][\w-]*)\s*:/g)) {
      props.push(dm[1]);
    }
    const bad = props.filter((p) => !ALLOWED_PROPS.has(p));
    expect(bad).toEqual([]);
  });

  it('ease-toy only appears next to press-release or snap-in (R-v5-05)', () => {
    const files = [...collectSource(SRC_DIR), TW_PATH];
    const offenders: string[] = [];
    for (const file of files) {
      const source = readFileSync(file, 'utf8');
      source.split('\n').forEach((line, i) => {
        if (/ease-toy/.test(line) && !/press-release|snap-in/.test(line)) {
          offenders.push(`${path.relative(REPO_ROOT, file)}:${i + 1}`);
        }
      });
    }
    expect(offenders).toEqual([]);
  });
});
